#[path = "solution.rs"]
mod solution;

use solution::{project_slug, qualified_ref, RepoPlan};

#[test]
fn qualified_refs_map_branches_and_tags() {
    assert_eq!(qualified_ref("branch", "main"), Some("refs/heads/main:refs/heads/main".into()));
    assert_eq!(qualified_ref("tag", "release/v1"), Some("refs/tags/release/v1:refs/tags/release/v1".into()));
}

#[test]
fn qualified_refs_reject_invalid_kind_and_names() {
    for (kind, name) in [
        ("commit", "main"),
        ("branch", ""),
        ("branch", "/main"),
        ("branch", "feature:x"),
        ("branch", "two words"),
        ("tag", "line\nbreak"),
        ("tag", "tab\tname"),
    ] {
        assert_eq!(qualified_ref(kind, name), None, "accepted ({kind:?}, {name:?})");
    }
}

#[test]
fn project_slug_handles_url_scp_style_and_ascii_trimming() {
    assert_eq!(project_slug("  https://example.test/team/project.git///\t"), Some("project".into()));
    assert_eq!(project_slug("git@example.test:group/repo.git"), Some("repo".into()));
    assert_eq!(project_slug("repo.git.git"), Some("repo.git".into()));
    assert_eq!(project_slug("plain-name"), Some("plain-name".into()));
}

#[test]
fn project_slug_rejects_empty_results() {
    for remote in ["", "   \t\n", "/", "////", "host:", ".git", "path/.git///"] {
        assert_eq!(project_slug(remote), None, "accepted {remote:?}");
    }
}

#[test]
fn tracked_refs_preserve_category_and_original_order_with_deduplication() {
    let plan = RepoPlan {
        primary: "main".into(),
        supporting: vec!["dev".into(), "main".into(), "bad name".into(), "dev".into(), "release".into()],
        tags: vec!["v2".into(), "v1".into(), "v2".into(), "main".into(), ":bad".into()],
    };
    let before = plan.clone();
    assert_eq!(plan.tracked_refs(), vec![
        "refs/heads/main:refs/heads/main",
        "refs/heads/dev:refs/heads/dev",
        "refs/heads/release:refs/heads/release",
        "refs/tags/v2:refs/tags/v2",
        "refs/tags/v1:refs/tags/v1",
        "refs/tags/main:refs/tags/main",
    ]);
    assert_eq!(plan, before);
}

#[test]
fn invalid_primary_does_not_block_valid_supporting_refs() {
    let plan = RepoPlan {
        primary: String::new(),
        supporting: vec!["next".into()],
        tags: vec![],
    };
    assert_eq!(plan.tracked_refs(), vec!["refs/heads/next:refs/heads/next"]);
}

